# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::Handoff::LegacyOperationsCheck do
  # "Source intents are saved at the checkpoint and reused on resume, and deleting or changing a terminal
  # intent after the checkpoint makes reconcile report a difference."
  # An expected-difference list that names an edited intent would explain away the very state difference
  # reconcile must report, so a receipt is listed only for an intent committed on both sides.
  it "lists no expected receipt for an intent whose state changed or that was deleted after the checkpoint" do
    intent = lambda do |invoice_id, state|
      {
        "id" => invoice_id, "company_id" => 11, "invoice_id" => invoice_id,
        "operation_id" => format("8f0c2a4e-1b2d-4c3e-9f00-%012d", invoice_id), "generation" => 1,
        "desired_entry_ids" => [invoice_id], "disposition" => "active", "state" => state,
        "created_at" => Time.utc(2026, 10, 1), "finished_at" => Time.utc(2026, 10, 1, 0, 1)
      }
    end
    source_intents = [intent.call(1, "committed"), intent.call(2, "committed"), intent.call(3, "failed"),
                      intent.call(4, "committed")]
    current_intents = [intent.call(1, "committed"), intent.call(2, "failed"), intent.call(3, "committed")]

    listed = described_class.listed_receipts(source_intents:, intents: current_intents, legacy_retired_at: nil)
    row_keys = listed.values.flatten.map(&:row_key)

    expect(listed.keys).to eq([11])
    expect(row_keys).to contain_exactly(Timekeeping::Handoff::Reconciliation::RECEIPT_LINK_KEY.call(intent.call(1, "committed")))
    expect(listed.values.flatten).to all(have_attributes(check: :operation_receipts, field: "state"))
  end

  # Intents are unique per company, invoice and operation, so another company's committed intent with the
  # same invoice and operation ids must not explain a state change made after the checkpoint.
  it "does not list a receipt for one company's intent because another company's matching intent was committed" do
    intent = lambda do |company_id, state|
      {
        "id" => company_id, "company_id" => company_id, "invoice_id" => 21,
        "operation_id" => "8f0c2a4e-1b2d-4c3e-9f00-000000000021", "generation" => 1,
        "desired_entry_ids" => [], "disposition" => "active", "state" => state,
        "created_at" => Time.utc(2026, 10, 1), "finished_at" => Time.utc(2026, 10, 1, 0, 1)
      }
    end

    listed = described_class.listed_receipts(
      source_intents: [intent.call(11, "failed"), intent.call(12, "committed")],
      intents: [intent.call(11, "committed"), intent.call(12, "committed")],
      legacy_retired_at: nil
    )

    expect(listed.keys).to eq([12])
  end
end
